import 'package:flutter/material.dart';
import 'package:permission_handler/permission_handler.dart';

class PermissionExample extends StatefulWidget {
  const PermissionExample({super.key});

  @override
  State<PermissionExample> createState() => _PermissionExampleState();
}

class _PermissionExampleState extends State<PermissionExample> {
  PermissionStatus _cameraStatus = PermissionStatus.denied;
  PermissionStatus _locationStatus = PermissionStatus.denied;
  PermissionStatus _microphoneStatus = PermissionStatus.denied;

  @override
  void initState() {
    super.initState();
    _checkPermissions();
  }

  /// 권한 상태 확인
  Future<void> _checkPermissions() async {
    final cameraStatus = await Permission.camera.status;
    final locationStatus = await Permission.location.status;
    final microphoneStatus = await Permission.microphone.status;

    setState(() {
      _cameraStatus = cameraStatus;
      _locationStatus = locationStatus;
      _microphoneStatus = microphoneStatus;
    });
  }

  /// 카메라 권한 요청
  Future<void> _requestCameraPermission() async {
    // 이미 허용된 경우
    if (await Permission.camera.isGranted) {
      _showMessage('카메라 권한이 이미 허용되어 있습니다');
      return;
    }

    // 권한 요청
    final status = await Permission.camera.request();

    setState(() {
      _cameraStatus = status;
    });

    // 결과에 따른 처리
    if (status.isGranted) {
      _showMessage('카메라 권한이 허용되었습니다');
      // 카메라 사용 로직 실행
    } else if (status.isPermanentlyDenied) {
      // 영구 거부 → 설정으로 이동 안내
      _showSettingsDialog('카메라');
    } else {
      _showMessage('카메라 권한이 거부되었습니다');
    }
  }

  /// 설정 화면 이동 다이얼로그
  void _showSettingsDialog(String permissionName) {
    showDialog(
      context: context,
      builder: (context) => AlertDialog(
        title: const Text('권한 필요'),
        content: Text(
          '$permissionName 권한이 영구적으로 거부되었습니다.\n'
          '설정에서 권한을 허용해주세요.',
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context),
            child: const Text('취소'),
          ),
          TextButton(
            onPressed: () {
              Navigator.pop(context);
              openAppSettings();  // 앱 설정 화면 열기
            },
            child: const Text('설정 열기'),
          ),
        ],
      ),
    );
  }

  void _showMessage(String message) {
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(content: Text(message)),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('권한 관리')),
      body: ListView(
        padding: const EdgeInsets.all(16),
        children: [
          _PermissionTile(
            icon: Icons.camera_alt,
            title: '카메라',
            status: _cameraStatus,
            onRequest: _requestCameraPermission,
          ),
          _PermissionTile(
            icon: Icons.location_on,
            title: '위치',
            status: _locationStatus,
            onRequest: () async {
              final status = await Permission.location.request();
              setState(() => _locationStatus = status);
            },
          ),
          _PermissionTile(
            icon: Icons.mic,
            title: '마이크',
            status: _microphoneStatus,
            onRequest: () async {
              final status = await Permission.microphone.request();
              setState(() => _microphoneStatus = status);
            },
          ),
        ],
      ),
    );
  }
}

class _PermissionTile extends StatelessWidget {
  final IconData icon;
  final String title;
  final PermissionStatus status;
  final VoidCallback onRequest;

  const _PermissionTile({
    required this.icon,
    required this.title,
    required this.status,
    required this.onRequest,
  });

  Color get _statusColor {
    switch (status) {
      case PermissionStatus.granted:
      case PermissionStatus.limited:
        return Colors.green;
      case PermissionStatus.denied:
        return Colors.orange;
      case PermissionStatus.permanentlyDenied:
      case PermissionStatus.restricted:
        return Colors.red;
      default:
        return Colors.grey;
    }
  }

  String get _statusText {
    switch (status) {
      case PermissionStatus.granted:
        return '허용됨';
      case PermissionStatus.limited:
        return '제한적 허용';
      case PermissionStatus.denied:
        return '거부됨';
      case PermissionStatus.permanentlyDenied:
        return '영구 거부';
      case PermissionStatus.restricted:
        return '제한됨';
      default:
        return '알 수 없음';
    }
  }

  @override
  Widget build(BuildContext context) {
    return Card(
      child: ListTile(
        leading: Icon(icon, size: 32),
        title: Text(title),
        subtitle: Text(
          _statusText,
          style: TextStyle(color: _statusColor, fontWeight: FontWeight.bold),
        ),
        trailing: status.isGranted
            ? const Icon(Icons.check_circle, color: Colors.green)
            : ElevatedButton(
                onPressed: onRequest,
                child: const Text('요청'),
              ),
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:permission_handler/permission_handler.dart';

class MultiplePermissionsExample extends StatefulWidget {
  const MultiplePermissionsExample({super.key});

  @override
  State<MultiplePermissionsExample> createState() =>
      _MultiplePermissionsExampleState();
}

class _MultiplePermissionsExampleState
    extends State<MultiplePermissionsExample> {
  Map<Permission, PermissionStatus> _statuses = {};

  // 앱에서 필요한 권한 목록
  final List<Permission> _requiredPermissions = [
    Permission.camera,
    Permission.microphone,
    Permission.location,
    Permission.photos,  // 사진 라이브러리
    Permission.notification,  // 알림
  ];

  @override
  void initState() {
    super.initState();
    _checkAllPermissions();
  }

  /// 모든 권한 상태 확인
  Future<void> _checkAllPermissions() async {
    final statuses = await _requiredPermissions.request();
    // 또는 상태만 확인: 
    // Map<Permission, PermissionStatus> statuses = {};
    // for (var permission in _requiredPermissions) {
    //   statuses[permission] = await permission.status;
    // }

    setState(() {
      _statuses = statuses;
    });
  }

  /// 모든 권한 한 번에 요청
  Future<void> _requestAllPermissions() async {
    // 여러 권한을 배열로 요청
    final statuses = await _requiredPermissions.request();

    setState(() {
      _statuses = statuses;
    });

    // 결과 분석
    final granted = statuses.values.where((s) => s.isGranted).length;
    final denied = statuses.values.where((s) => s.isDenied).length;
    final permanentlyDenied =
        statuses.values.where((s) => s.isPermanentlyDenied).length;

    String message = '$granted개 허용';
    if (denied > 0) message += ', $denied개 거부';
    if (permanentlyDenied > 0) message += ', $permanentlyDenied개 영구거부';

    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(content: Text(message)),
    );
  }

  /// 필수 권한이 모두 허용되었는지 확인
  bool get _allRequiredGranted {
    return _statuses.values.every((status) => status.isGranted);
  }

  /// 영구 거부된 권한이 있는지 확인
  bool get _hasPermanentlyDenied {
    return _statuses.values.any((status) => status.isPermanentlyDenied);
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('권한 일괄 관리')),
      body: Column(
        children: [
          // 상태 요약
          Container(
            width: double.infinity,
            padding: const EdgeInsets.all(16),
            color: _allRequiredGranted
                ? Colors.green.shade100
                : Colors.orange.shade100,
            child: Column(
              children: [
                Icon(
                  _allRequiredGranted ? Icons.check_circle : Icons.warning,
                  size: 48,
                  color: _allRequiredGranted ? Colors.green : Colors.orange,
                ),
                const SizedBox(height: 8),
                Text(
                  _allRequiredGranted
                      ? '모든 권한이 허용되었습니다'
                      : '일부 권한이 필요합니다',
                  style: const TextStyle(
                    fontSize: 16,
                    fontWeight: FontWeight.bold,
                  ),
                ),
              ],
            ),
          ),

          // 권한 목록
          Expanded(
            child: ListView.builder(
              itemCount: _requiredPermissions.length,
              itemBuilder: (context, index) {
                final permission = _requiredPermissions[index];
                final status = _statuses[permission] ?? PermissionStatus.denied;

                return ListTile(
                  leading: _getPermissionIcon(permission),
                  title: Text(_getPermissionName(permission)),
                  trailing: _buildStatusChip(status),
                  onTap: () async {
                    if (status.isPermanentlyDenied) {
                      await openAppSettings();
                    } else if (!status.isGranted) {
                      final newStatus = await permission.request();
                      setState(() {
                        _statuses[permission] = newStatus;
                      });
                    }
                  },
                );
              },
            ),
          ),

          // 하단 버튼
          Padding(
            padding: const EdgeInsets.all(16),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                if (_hasPermanentlyDenied)
                  OutlinedButton.icon(
                    onPressed: () => openAppSettings(),
                    icon: const Icon(Icons.settings),
                    label: const Text('앱 설정 열기'),
                  ),
                const SizedBox(height: 8),
                ElevatedButton(
                  onPressed: _allRequiredGranted ? null : _requestAllPermissions,
                  child: Text(
                    _allRequiredGranted ? '모든 권한 허용됨' : '모든 권한 요청',
                  ),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }

  Widget _getPermissionIcon(Permission permission) {
    IconData icon;
    switch (permission) {
      case Permission.camera:
        icon = Icons.camera_alt;
        break;
      case Permission.microphone:
        icon = Icons.mic;
        break;
      case Permission.location:
        icon = Icons.location_on;
        break;
      case Permission.photos:
        icon = Icons.photo_library;
        break;
      case Permission.notification:
        icon = Icons.notifications;
        break;
      default:
        icon = Icons.security;
    }
    return Icon(icon);
  }

  String _getPermissionName(Permission permission) {
    switch (permission) {
      case Permission.camera:
        return '카메라';
      case Permission.microphone:
        return '마이크';
      case Permission.location:
        return '위치';
      case Permission.photos:
        return '사진 라이브러리';
      case Permission.notification:
        return '알림';
      default:
        return permission.toString();
    }
  }

  Widget _buildStatusChip(PermissionStatus status) {
    Color color;
    String text;

    switch (status) {
      case PermissionStatus.granted:
        color = Colors.green;
        text = '허용';
        break;
      case PermissionStatus.limited:
        color = Colors.blue;
        text = '제한적';
        break;
      case PermissionStatus.denied:
        color = Colors.orange;
        text = '거부';
        break;
      case PermissionStatus.permanentlyDenied:
        color = Colors.red;
        text = '영구거부';
        break;
      default:
        color = Colors.grey;
        text = '알 수 없음';
    }

    return Chip(
      label: Text(text, style: const TextStyle(color: Colors.white, fontSize: 12)),
      backgroundColor: color,
      padding: EdgeInsets.zero,
    );
  }
}

