import 'package:flutter/material.dart';
import 'package:permission_handler/permission_handler.dart';

/// 권한 요청 결과
enum PermissionResult {
  granted,       // 허용됨
  denied,        // 거부됨 (다시 요청 가능)
  permanentlyDenied,  // 영구 거부 (설정으로 이동 필요)
  restricted,    // 시스템 제한
}

/// 권한 관리 서비스
class PermissionService {
  /// 단일 권한 요청 (설명 다이얼로그 포함)
  static Future<PermissionResult> requestWithRationale({
    required BuildContext context,
    required Permission permission,
    required String title,
    required String message,
  }) async {
    // 1. 현재 상태 확인
    var status = await permission.status;

    // 이미 허용됨
    if (status.isGranted) {
      return PermissionResult.granted;
    }

    // 영구 거부됨
    if (status.isPermanentlyDenied) {
      final goToSettings = await _showSettingsDialog(
        context: context,
        title: title,
        message: '$message\n\n권한이 영구적으로 거부되어 설정에서 직접 허용해야 합니다.',
      );
      if (goToSettings) {
        await openAppSettings();
      }
      return PermissionResult.permanentlyDenied;
    }

    // 2. 권한 요청 전 설명 다이얼로그 (선택적)
    if (status.isDenied) {
      final shouldRequest = await _showRationaleDialog(
        context: context,
        title: title,
        message: message,
      );

      if (!shouldRequest) {
        return PermissionResult.denied;
      }
    }

    // 3. 권한 요청
    status = await permission.request();

    // 4. 결과 반환
    if (status.isGranted) {
      return PermissionResult.granted;
    } else if (status.isPermanentlyDenied) {
      return PermissionResult.permanentlyDenied;
    } else if (status.isRestricted) {
      return PermissionResult.restricted;
    } else {
      return PermissionResult.denied;
    }
  }

  /// 카메라 권한 요청
  static Future<PermissionResult> requestCamera(BuildContext context) {
    return requestWithRationale(
      context: context,
      permission: Permission.camera,
      title: '카메라 권한',
      message: '사진 촬영을 위해 카메라 접근 권한이 필요합니다.',
    );
  }

  /// 위치 권한 요청
  static Future<PermissionResult> requestLocation(BuildContext context) {
    return requestWithRationale(
      context: context,
      permission: Permission.location,
      title: '위치 권한',
      message: '현재 위치를 확인하기 위해 위치 접근 권한이 필요합니다.',
    );
  }

  /// 갤러리/사진 권한 요청
  static Future<PermissionResult> requestPhotos(BuildContext context) {
    return requestWithRationale(
      context: context,
      permission: Permission.photos,
      title: '사진 라이브러리 권한',
      message: '사진을 선택하기 위해 사진 라이브러리 접근 권한이 필요합니다.',
    );
  }

  /// 마이크 권한 요청
  static Future<PermissionResult> requestMicrophone(BuildContext context) {
    return requestWithRationale(
      context: context,
      permission: Permission.microphone,
      title: '마이크 권한',
      message: '음성 녹음을 위해 마이크 접근 권한이 필요합니다.',
    );
  }

  /// 알림 권한 요청
  static Future<PermissionResult> requestNotification(BuildContext context) {
    return requestWithRationale(
      context: context,
      permission: Permission.notification,
      title: '알림 권한',
      message: '중요한 알림을 받으시려면 알림 권한을 허용해주세요.',
    );
  }

  /// 권한 설명 다이얼로그
  static Future<bool> _showRationaleDialog({
    required BuildContext context,
    required String title,
    required String message,
  }) async {
    return await showDialog<bool>(
      context: context,
      builder: (context) => AlertDialog(
        title: Text(title),
        content: Text(message),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context, false),
            child: const Text('취소'),
          ),
          ElevatedButton(
            onPressed: () => Navigator.pop(context, true),
            child: const Text('권한 요청'),
          ),
        ],
      ),
    ) ?? false;
  }

  /// 설정 이동 다이얼로그
  static Future<bool> _showSettingsDialog({
    required BuildContext context,
    required String title,
    required String message,
  }) async {
    return await showDialog<bool>(
      context: context,
      builder: (context) => AlertDialog(
        title: Text(title),
        content: Text(message),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context, false),
            child: const Text('취소'),
          ),
          ElevatedButton(
            onPressed: () => Navigator.pop(context, true),
            child: const Text('설정 열기'),
          ),
        ],
      ),
    ) ?? false;
  }
}

