import 'dart:io';
import 'package:flutter/material.dart';
import 'package:permission_handler/permission_handler.dart';

class PlatformPermissionsExample extends StatefulWidget {
  const PlatformPermissionsExample({super.key});

  @override
  State<PlatformPermissionsExample> createState() =>
      _PlatformPermissionsExampleState();
}

class _PlatformPermissionsExampleState
    extends State<PlatformPermissionsExample> {

  /// 저장소 권한 (Android 버전별 다름)
  Future<void> _requestStoragePermission() async {
    PermissionStatus status;

    if (Platform.isAndroid) {
      // Android 13 (API 33) 이상: 세분화된 미디어 권한
      // Android 12 이하: 일반 저장소 권한
      final androidInfo = await Permission.storage.status;

      // Android 13+에서는 photos, videos, audio 개별 요청
      if (await Permission.photos.status.isDenied) {
        status = await Permission.photos.request();
      }

      // 또는 manageExternalStorage (모든 파일 접근, Play Store 심사 엄격)
      // status = await Permission.manageExternalStorage.request();
    } else {
      // iOS: 사진 라이브러리 권한
      status = await Permission.photos.request();
    }
  }

  /// 위치 권한 (whileInUse vs always)
  Future<void> _requestLocationPermissions() async {
    // 1. 먼저 '앱 사용 중' 권한 요청
    var status = await Permission.locationWhenInUse.request();

    if (!status.isGranted) {
      _showMessage('위치 권한이 거부되었습니다');
      return;
    }

    // 2. '항상' 권한이 필요한 경우 (백그라운드 위치 추적)
    // 주의: 먼저 whileInUse가 허용되어야 함
    final alwaysStatus = await Permission.locationAlways.request();

    if (alwaysStatus.isGranted) {
      _showMessage('백그라운드 위치 권한 허용됨');
    } else {
      _showMessage('앱 사용 중에만 위치 사용 가능');
    }
  }

  /// 블루투스 권한 (Android 12+, iOS)
  Future<void> _requestBluetoothPermissions() async {
    if (Platform.isAndroid) {
      // Android 12+에서 필요한 블루투스 권한들
      final statuses = await [
        Permission.bluetoothScan,
        Permission.bluetoothConnect,
        Permission.bluetoothAdvertise,
      ].request();

      final allGranted = statuses.values.every((s) => s.isGranted);
      _showMessage(allGranted ? '블루투스 권한 허용됨' : '일부 권한 거부됨');
    } else {
      // iOS
      final status = await Permission.bluetooth.request();
      _showMessage(status.isGranted ? '블루투스 권한 허용됨' : '권한 거부됨');
    }
  }

  /// 알림 권한 (Android 13+, iOS)
  Future<void> _requestNotificationPermission() async {
    // Android 13 (API 33) 이상에서만 런타임 권한 필요
    // iOS에서는 항상 필요
    final status = await Permission.notification.request();

    if (status.isGranted) {
      _showMessage('알림 권한 허용됨');
    } else if (status.isPermanentlyDenied) {
      _showMessage('설정에서 알림을 허용해주세요');
      await openAppSettings();
    } else {
      _showMessage('알림 권한 거부됨');
    }
  }

  /// iOS 추적 투명성 (ATT)
  Future<void> _requestTrackingPermission() async {
    if (!Platform.isIOS) {
      _showMessage('iOS 전용 기능입니다');
      return;
    }

    // iOS 14.5+ App Tracking Transparency
    final status = await Permission.appTrackingTransparency.request();

    if (status.isGranted) {
      _showMessage('추적 허용됨');
      // IDFA 사용 가능
    } else {
      _showMessage('추적 거부됨');
      // 개인화 광고 비활성화
    }
  }

  void _showMessage(String message) {
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(content: Text(message)),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('플랫폼별 권한')),
      body: ListView(
        padding: const EdgeInsets.all(16),
        children: [
          _buildSection('저장소/미디어', [
            _buildButton('저장소 권한', _requestStoragePermission),
          ]),
          _buildSection('위치', [
            _buildButton('위치 권한 (단계별)', _requestLocationPermissions),
          ]),
          _buildSection('블루투스', [
            _buildButton('블루투스 권한', _requestBluetoothPermissions),
          ]),
          _buildSection('알림', [
            _buildButton('알림 권한', _requestNotificationPermission),
          ]),
          if (Platform.isIOS)
            _buildSection('iOS 전용', [
              _buildButton('추적 투명성 (ATT)', _requestTrackingPermission),
            ]),
        ],
      ),
    );
  }

  Widget _buildSection(String title, List<Widget> children) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Padding(
          padding: const EdgeInsets.symmetric(vertical: 8),
          child: Text(title, style: const TextStyle(fontWeight: FontWeight.bold, fontSize: 16)),
        ),
        ...children,
        const SizedBox(height: 16),
      ],
    );
  }

  Widget _buildButton(String label, VoidCallback onPressed) {
    return Padding(
      padding: const EdgeInsets.only(bottom: 8),
      child: ElevatedButton(
        onPressed: onPressed,
        child: Text(label),
      ),
    );
  }
}

